// Script + cache rules for GET /audio/:locationId. The script is built from the SAME display scores the
// place panel shows (getDisplayScore), never from made-up defaults, and never quotes a number: the panel's
// 0-5 scores are not "out of 10", and an AI estimate is not a measurement.

// Bump when the spoken script changes meaningfully. It is part of the stored audio's public id, so audio
// generated by an older script (e.g. the old "rated 3.0 out of 10" fallback) no longer counts as cached.
export const AUDIO_SCRIPT_VERSION = 2;

export const audioPublicId = (locationId) => `audio_${locationId}_v${AUDIO_SCRIPT_VERSION}`;

// Cloudinary's secure_url ends in .../sensemap-audio/<public_id>.<ext>
export const isCurrentAudioUrl = (url, locationId) =>
  typeof url === "string" && url.includes(`/${audioPublicId(locationId)}.`);

// The cache write stamps audioGeneratedAt just BEFORE Prisma stamps @updatedAt on the same update, so a
// strict `generatedAt > updatedAt` can never be true. Allow a few seconds of skew.
const CACHE_SKEW_MS = 5000;

export function isAudioCacheValid(location) {
  if (!location?.audioUrl || !location.audioGeneratedAt) return false;
  if (!isCurrentAudioUrl(location.audioUrl, location.id)) return false;
  return new Date(location.audioGeneratedAt).getTime() >= new Date(location.updatedAt).getTime() - CACHE_SKEW_MS;
}

export const NO_AUDIO_MESSAGE = "No audio is available for this place yet.";

/** { available: true } or { available: false, reason } for a display-score object (+ lowConfidence flag). */
export function audioAvailability(display, lowConfidence = false) {
  if (!display || display.source === "category") return { available: false, reason: "no_scores" };
  if (lowConfidence) return { available: false, reason: "low_confidence" };
  const vals = [display.noise, display.lighting, display.crowd];
  if (vals.some((v) => !Number.isFinite(v))) return { available: false, reason: "no_scores" };
  return { available: true };
}

export function scoreToLabel(score) {
  if (score <= 2) return "very low";
  if (score <= 3) return "moderate";
  if (score <= 4) return "high";
  return "very high";
}

function noiseLabel(score) {
  if (score <= 2) return "very quiet";
  if (score <= 3) return "moderately quiet";
  if (score <= 4) return "somewhat noisy";
  return "very loud";
}

function lightingLabel(score) {
  if (score <= 2) return "dim and soft";
  if (score <= 3) return "moderate";
  if (score <= 4) return "bright";
  return "very bright";
}

function crowdLabel(score) {
  if (score <= 2) return "very uncrowded";
  if (score <= 3) return "moderately busy";
  if (score <= 4) return "busy";
  return "very crowded";
}

/**
 * @param display   the object getDisplayScore() returns ({ noise, lighting, crowd, source })
 * @param provenance { realReviews } how many real visitor reviews exist (0 = bot/curated only)
 * Returns null when there is nothing honest to say (callers must check audioAvailability first).
 */
export function buildAudioScript(location, display, provenance = {}, aiInsights = null) {
  if (!audioAvailability(display).available) return null;

  let caveat = "";
  if (display.source === "estimated") {
    caveat = " These are AI estimates from public information, not reports from visitors.";
  } else if (!(provenance.realReviews > 0)) {
    caveat = " These ratings are curated from public accessibility information, not reports from visitors.";
  }

  const bestTimePart = aiInsights?.bestTime ? ` ${aiInsights.bestTime}.` : "";
  return `${location.name}.${caveat} Noise level: ${noiseLabel(display.noise)}. Lighting: ${lightingLabel(display.lighting)}. Crowd level: ${crowdLabel(display.crowd)}.${bestTimePart}`;
}
